class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict

        # Count occurrences of all special substrings
        count = defaultdict(int)
        n = len(s)

        # Generate all special substrings and count them
        for i in range(n):
            char = s[i]
            length = 1
            # Extend the special substring as long as characters are the same
            for j in range(i, n):
                if s[j] == char:
                    count[(char, length)] += 1
                    length += 1
                else:
                    break

        # Find the maximum length special substring that occurs at least 3 times
        max_length = -1
        for (char, length), freq in count.items():
            if freq >= 3:
                max_length = max(max_length, length)

        return max_length
